                            break;
                        case "Notifications":
                            <NotificationsSection Prefs="@_notifications" OnSave="SaveNotificationsAsync" />
                            break;
                        case "Security":
                            <SecuritySection Settings="@_security"
                                             OnRevokeSession="RevokeSessionAsync"
                                             OnChangePassword="ChangePasswordAsync"
                                             OnToggle2FA="Toggle2FAAsync" />
                            break;
                        case "Appearance":
