{"file_text": "@using sv_99304bb355b545b982f9a7c49c505c18.Services

<h4 class="mb-4">Appearance Settings</h4>

@if (_settings is not null)
{
    <div class="row">
        <div class="col-md-7">
            <!-- Theme -->
            <div class="mb-4">
                <h6>Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check form-check-inline">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <h6>Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check form-check-inline">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <!-- Language -->
            <div class="mb-4">
                <h6>Language</h6>
                <select class="form-select" style="max-width:250px;" @bind="_language">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync">Save</button>

            @if (_showSuccess)
            {
                <div class="alert alert-success mt-3 fade show" role="alert">
                    Appearance settings saved!
                </div>
            }
        </div>

        <!-- Live Preview -->
        <div class="col-md-5">
            <div class="card @GetPreviewClasses()" style="@GetPreviewStyles()">
                <div class="card-header">
                    <strong>Live Preview</strong>
                </div>
                <div class="card-body">
                    <h6 style="@GetPreviewFontStyle()">Sample Heading</h6>
                    <p style="@GetPreviewFontStyle()" class="@(_compactMode ? "mb-1" : "mb-3")">
                        This is how your content will look with the selected settings.
                    </p>
                    <div class="d-flex gap-2 @(_compactMode ? "" : "mt-3")">
                        <button class="btn btn-sm btn-primary">Action</button>
                        <button class="btn btn-sm btn-outline-secondary">Cancel</button>
                    </div>
                    <p class="mt-2 text-muted" style="@GetPreviewFontStyle()">
                        Language: @_language | Compact: @(_compactMode ? "On" : "Off")
                    </p>
                </div>
            </div>
        </div>
    </div>
}
else
{
    <div class="text-center py-4">
        <div class="spinner-border" role="status"></div>
    </div>
}

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (Settings is not null && _settings != Settings)
        {
            _settings = Settings;
            _theme = _settings.Theme;
            _fontSize = _settings.FontSize;
            _language = _settings.Language;
            _compactMode = _settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        return _theme == "Dark" ? "text-bg-dark" : "";
    }

    private string GetPreviewStyles()
    {
        var bg = _theme switch
        {
            "Dark" => "background-color:#1e1e1e; color:#fff;",
            "System" => "background-color:#f0f0f0;",
            _ => "background-color:#fff;"
        };
        return bg;
    }

    private string GetPreviewFontStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "font-size:0.85rem;",
            "Large" => "font-size:1.2rem;",
            _ => "font-size:1rem;"
        };
        return size;
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _settings = updated;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
